package com.demo;
import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;
public class WelcomeServlet extends HttpServlet {
  private String welcome;
  public void init() throws ServletException {
    welcome = getInitParameter("welcome");
  }
  protected void doGet(HttpServletRequest request, HttpServletResponse response)
      throws ServletException, IOException {
    response.setContentType("text/html;charset=UTF-8");
    response.getWriter().println(welcome);
  }
}
<!-- web.xml -->
<servlet>
  <servlet-name>welcome</servlet-name>
  <servlet-class>com.demo.WelcomeServlet</servlet-class>
  <init-param><param-name>welcome</param-name><param-value>欢迎光临</param-value></init-param>
  <load-on-startup>1</load-on-startup>
</servlet>
<servlet-mapping><servlet-name>welcome</servlet-name><url-pattern>/welcome</url-pattern></servlet-mapping>
